~~~csharp
public sealed record Chunk(string Id, string DocId, string SectionPath, string Text, string Version, DateOnly EffectiveFrom, string[] AccessLabels, string ParentId);

public static IEnumerable<Chunk> ChunkPolicy(PolicyDocument doc, Tokenizer tokenizer, int maxTokens = 500)
{
    foreach (var section in doc.Sections)                                        // structural: headings and clauses
    {
        var path = string.Join(" > ", section.HeadingPath);
        var parentId = doc.Id + ":" + section.Number;
        foreach (var block in SplitByParagraphs(section, tokenizer, maxTokens))
        {
            var text = path + "\n" + block.Text;                                 // prepend section path for context
            yield return new Chunk(parentId + ":" + block.Index, doc.Id, path, text, doc.Version, doc.EffectiveFrom, doc.AccessLabels, parentId);
        }
        foreach (var table in section.Tables)                                    // keep tables intact with headers
            yield return new Chunk(parentId + ":t" + table.Index, doc.Id, path, path + "\n" + table.ToMarkdown(), doc.Version, doc.EffectiveFrom, doc.AccessLabels, parentId);
    }
}
// At query time: retrieve child chunks, then expand to parent sections (deduplicated) for the prompt
