public static IReadOnlyList<SearchHit> ReciprocalRankFusion(IReadOnlyList<SearchHit> keyword, IReadOnlyList<SearchHit> vector, int k = 60, int take = 40)
{
    var scores = new Dictionary<string, (SearchHit Hit, double Score)>();
    void Add(IReadOnlyList<SearchHit> list)
    {
        for (var rank = 0; rank < list.Count; rank++)
        {
            var h = list[rank];
            var s = 1.0 / (k + rank + 1);
            scores[h.ChunkId] = scores.TryGetValue(h.ChunkId, out var existing) ? (existing.Hit, existing.Score + s) : (h, s);
        }
    }
    Add(keyword); Add(vector);
    return scores.Values.OrderByDescending(x => x.Score).Take(take).Select(x => x.Hit).ToList();
}

// Then rerank with a cross-encoder service and keep the best 6
