public sealed record EvalCase(string Id, string Input, string ExpectedCategory, bool ExpectedVulnerable, string[] Tags);

public async Task<EvalReport> RunAsync(IReadOnlyList<EvalCase> cases, CancellationToken ct)
{
    var results = new ConcurrentBag<(EvalCase Case, Classification Output)>();
    await Parallel.ForEachAsync(cases, new ParallelOptions { MaxDegreeOfParallelism = 8, CancellationToken = ct }, async (c, token) =>
        results.Add((c, await classifier.ClassifyAsync(c.Input, token))));

