public sealed class GuardedChatClient(IChatClient inner, IPiiTokenizer pii, IInjectionDetector injection, IContentSafety safety) : DelegatingChatClient(inner)
{
    public override async Task<ChatResponse> GetResponseAsync(IEnumerable<ChatMessage> messages, ChatOptions? options = null, CancellationToken ct = default)
    {
        var vault = new PiiVault();
        var sanitized = messages.Select(m => new ChatMessage(m.Role, pii.Tokenize(m.Text ?? "", vault))).ToList();   // "GB29..." -> <IBAN_1>
        if (await injection.IsSuspiciousAsync(sanitized.Last().Text ?? "", ct)) return Refusal("I can't help with that request.");

        var response = await base.GetResponseAsync(sanitized, options, ct);

        var verdict = await safety.CheckAsync(response.Text, ct);
        if (!verdict.Allowed) return Refusal("I can't provide that. Please contact an adviser.");
        return new ChatResponse(new ChatMessage(ChatRole.Assistant, pii.Detokenize(response.Text, vault)));   // restore only the user's own values
    }
    static ChatResponse Refusal(string text) => new(new ChatMessage(ChatRole.Assistant, text));
}
