public sealed class ConversationContext(IChatClient summarizer, Tokenizer tokenizer, int budgetTokens = 3000)
{
    private readonly List<ChatMessage> _recent = [];
    private string _summary = "";

    public async Task AddAsync(ChatMessage message, CancellationToken ct)
    {
        _recent.Add(message);
        while (tokenizer.CountTokens(string.Join("\n", _recent.Select(m => m.Text))) > budgetTokens && _recent.Count > 4)
