            var r = await summarizer.GetResponseAsync(
                [new(ChatRole.System, "Update the running summary of a banking support conversation. Keep facts, decisions, open questions. No card or account numbers."),
                 new(ChatRole.User, "Summary so far:\n" + _summary + "\n\nNew turns:\n" + string.Join("\n", oldest.Select(m => m.Role + ": " + m.Text)))],
                new ChatOptions { Temperature = 0, MaxOutputTokens = 300 }, ct);
            _summary = r.Text;
        }
    }

    public IEnumerable<ChatMessage> ForPrompt(string systemPrompt) =>
        new[] { new ChatMessage(ChatRole.System, systemPrompt + "\n\nConversation summary:\n" + _summary) }.Concat(_recent);
}
