public sealed class IngestionWorker(IDocumentParser parser, IChunker chunker, IEmbeddingGenerator<string, Embedding<float>> embedder, ISearchIndex index, IAclResolver acls)
{
    public async Task HandleAsync(SourceChange change, CancellationToken ct)
    {
        if (change.Kind == ChangeKind.Deleted || change.Kind == ChangeKind.PermissionsRevokedForAll)
        {
            await index.DeleteByDocumentAsync(change.DocumentId, ct);                 // fast path: remove before anything else
            return;
        }
        var doc = await parser.ParseAsync(change.Uri, ct);                             // layout-aware, OCR when needed
        if (doc.Quality < ParseQuality.Acceptable) { await deadLetter.ParkAsync(change, "poor parse", ct); return; }

        var labels = await acls.ResolveAsync(change.DocumentId, ct);                   // groups -> access labels
        var chunks = chunker.Chunk(doc).Select(c => c with { AccessLabels = labels, Version = doc.Version }).ToList();
        var vectors = await embedder.GenerateAsync(chunks.Select(c => c.Text), cancellationToken: ct);
        await index.ReplaceDocumentAsync(change.DocumentId, chunks.Zip(vectors, (c, v) => c with { Embedding = v.Vector }), ct);   // idempotent per doc id + version
    }
}
