            RecallAt5: c.RelevantChunkIds.Any(id => top.Any(x => x.Id == id)),
            Faithfulness: claims.Count == 0 ? 1 : supported / (double)claims.Count,
            CorrectAbstention: !c.Answerable ? answer.Abstained : (bool?)null));
    }
