public async Task<AgentResult> RunAsync(string goal, AgentProfile profile, CancellationToken ct)
{
    var history = new List<ChatMessage> { new(ChatRole.System, profile.SystemPrompt), new(ChatRole.User, goal) };
    var options = new ChatOptions { Tools = profile.Tools, Temperature = 0 };   // narrow toolset per task
    var budget = new AgentBudget(maxSteps: 8, maxTokens: 40_000, maxDuration: TimeSpan.FromSeconds(90));

    for (var step = 0; step < budget.MaxSteps; step++)
    {
        var response = await chat.GetResponseAsync(history, options, ct);
        budget.Consume(response.Usage);
        if (budget.Exceeded) return AgentResult.Stopped("budget", history);

        var calls = response.Messages.SelectMany(m => m.Contents.OfType<FunctionCallContent>()).ToList();
        if (calls.Count == 0) return AgentResult.Completed(response.Text, history);

        history.AddRange(response.Messages);
        foreach (var call in calls)
        {
            if (loopDetector.IsRepeat(call)) return AgentResult.Stopped("repetition", history);
            var result = await toolHost.InvokeAsync(call, ct);                // validates args, enforces authz, traces span
            history.Add(new ChatMessage(ChatRole.Tool, [new FunctionResultContent(call.CallId, result)]));
        }
    }
    return AgentResult.Stopped("max-steps", history);
}
