public sealed class FallbackChatClient(IReadOnlyList<(string Name, IChatClient Client, ResiliencePipeline Pipeline)> targets, ILogger<FallbackChatClient> log) : IChatClient
{
    public async Task<ChatResponse> GetResponseAsync(IEnumerable<ChatMessage> messages, ChatOptions? options = null, CancellationToken ct = default)
