[Function(nameof(KycRefreshOrchestrator))]
public static async Task<KycOutcome> KycRefreshOrchestrator([OrchestrationTrigger] TaskOrchestrationContext ctx)
{
    var input = ctx.GetInput<KycRefreshInput>()!;
    var retry = TaskOptions.FromRetryPolicy(new RetryPolicy(5, TimeSpan.FromSeconds(10), backoffCoefficient: 2));

    await ctx.CallActivityAsync(nameof(RequestDocuments), input.CustomerId, retry);
    DocumentSet received;
    try { received = await ctx.WaitForExternalEvent<DocumentSet>("DocumentsUploaded", TimeSpan.FromDays(5)); }   // durable wait
    catch (TaskCanceledException)                                                    // timed out: chase the customer, wait once more
    {
        await ctx.CallActivityAsync(nameof(ChaseCustomer), input.CustomerId, retry);
        received = await ctx.WaitForExternalEvent<DocumentSet>("DocumentsUploaded", TimeSpan.FromDays(5));   // a second timeout fails into escalation
    }

    var extraction = await ctx.CallActivityAsync<ExtractionResult>(nameof(ExtractWithLlm), received, retry);   // result recorded; replay won't re-call the model
    var screening = await ctx.CallActivityAsync<ScreeningResult>(nameof(RunSanctionsScreening), extraction.Person, retry);

    if (extraction.Confidence < 0.9 || screening.PotentialMatch)
    {
        await ctx.CallActivityAsync(nameof(CreateReviewTask), new ReviewTask(input.CustomerId, extraction, screening));
        var decision = await ctx.WaitForExternalEvent<ReviewDecision>("ReviewCompleted", TimeSpan.FromDays(3));
        return decision.Approved ? KycOutcome.Refreshed : KycOutcome.Escalated;
    }
    return KycOutcome.Refreshed;
}
