// Host loop for a browser agent: sandboxed browser, domain allow-list, confirmation before submits
public async Task<AgentResult> RunAsync(string task, CancellationToken ct)
{
    await using var browser = await sandbox.LaunchAsync(new BrowserOptions { AllowedHosts = ["vendorportal.example", "legacy-ops.internal"], Incognito = true });
    var history = new List<ChatMessage> { new(ChatRole.System, AgentPrompts.BrowserOperator), new(ChatRole.User, task) };

    for (int step = 0; step < 30; step++)
    {
        var shot = await browser.ScreenshotAsync(ct);
        history.Add(new ChatMessage(ChatRole.User, [new DataContent(shot, "image/png"), new TextContent("Current screen")]));
        var action = await model.NextActionAsync(history, ct);                     // click, type, scroll, done
        await audit.RecordStepAsync(task, step, shot, action, ct);                  // screenshots and actions kept for review

        if (action.Kind == ActionKind.Done) return AgentResult.Completed(action.Summary);
        if (action.IsSubmit && !await human.ConfirmAsync(action.Describe(), shot, ct)) return AgentResult.Stopped("not confirmed");
        if (!browser.IsAllowed(action.TargetUrl)) return AgentResult.Stopped("domain not allowed");
        await browser.ExecuteAsync(action, ct);
    }
    return AgentResult.Stopped("step limit");
}
