// Durable agent run: each step is a recorded activity; state lives outside the context window
[Function(nameof(CreditFileAgent))]
public static async Task<AgentOutcome> CreditFileAgent([OrchestrationTrigger] TaskOrchestrationContext ctx)
{
    var mandate = ctx.GetInput<AgentMandate>()!;                       // tools, data scope, budget, owner
    var state = await ctx.CallActivityAsync<AgentState>(nameof(LoadOrInitState), mandate.RunId);

    var plan = await ctx.CallActivityAsync<Plan>(nameof(DraftPlan), state);
    var approved = await ctx.WaitForExternalEvent<bool>("PlanApproved", TimeSpan.FromHours(8));   // human checkpoint
    if (!approved) return AgentOutcome.Rejected;

    foreach (var step in plan.Steps)
    {
        if (state.CostUsd > mandate.BudgetUsd || state.Steps >= mandate.MaxSteps)
            return await ctx.CallActivityAsync<AgentOutcome>(nameof(PauseForReview), state);    // never silently overspend
        state = await ctx.CallActivityAsync<AgentState>(nameof(ExecuteStep), new StepInput(state, step));   // model + read-only tools, recorded
        await ctx.CallActivityAsync(nameof(SaveState), state);                                  // compaction: findings, decisions, open questions
    }

    var draft = await ctx.CallActivityAsync<CreditFileDraft>(nameof(AssembleDraft), state);
    await ctx.CallActivityAsync(nameof(RequestAnalystReview), draft);                           // final human sign-off, agent cannot submit
    return AgentOutcome.AwaitingReview;
}
